import sys
import six
from wrapt import decorator


def override_exception(exception_to_override, new_exception_name):
    """
    *DEPRECATED*
    Use ute_common_util.decorators.exception.override_exception
    Remove date: July 1, 2017
    """
    @decorator
    def translate_exceptions(wrapped, instance, args, kwargs):
        """A decorator that translates any exception to the other while keeping traceback"""
        try:
            return wrapped(*args, **kwargs)
        except exception_to_override as e:
            six.reraise(new_exception_name, sys.exc_info()[1], sys.exc_info()[2])
    return translate_exceptions
